import { test, expect } from '../../fixtures/index.js';
import { meta } from 'reporting-labs';
import { AccountRecordPage } from '../../pages/AccountRecordPage.js';
import { NewContactDialog } from '../../pages/NewContactDialog.js';
import {
  expectRecordTitle,
  expectToast,
  relatedListRecord,
  showRelatedList,
  waitForSpinners,
} from '../../support/lightning.js';
import { soqlValue } from '../../support/api.js';

test.describe('SF-219 Create Contact with valid Last Name (positive)', () => {
  test.describe.configure({ mode: 'parallel' });

  test(
    'TC-SF-219-026 Create Contact with valid Last Name (positive)',
    { tag: ['@functional', '@P2', '@SF-219', '@persona:system-admin', '@mandatory'] },
    async ({ page, data, sf }) => {
      meta({
        priority: 'P2',
        severity: 'minor',
        feature: 'Contact',
        story: 'SF-219',
        owner: 'qa-agent',
        testCase: 'TC-SF-219-026',
      });
      const accountRecordPage = new AccountRecordPage(page);
      const newContactDialog = new NewContactDialog(page);
      const firstName = data.unique('first-name');
      const lastName = data.unique('last-name');
      await data.create('account-contact', ['Account']);
      await test.step('1. Open New Contact dialog from Account', async () => {
        // Expected (APPROVED_REQUIREMENT; SF-219#AC2): New Contact modal opens with Account Name pre-populated
        await accountRecordPage.open(data.id('Account'));
        await showRelatedList(accountRecordPage.contactsRelatedList, accountRecordPage.relatedTab);
        await accountRecordPage.contactsNewButton.click();
        await expect(newContactDialog.root).toBeVisible();
        await expect(newContactDialog.accountId).toHaveValue(data.value('Account', 'Name'));
      });
      await test.step('2. Enter First and Last Name', async () => {
        // Expected (APPROVED_REQUIREMENT; SF-219#AC2): First Name and Last Name fields accept the input
        await newContactDialog.firstName.fill(firstName);
        await newContactDialog.lastName.fill(lastName);
        await expect(newContactDialog.firstName).toHaveValue(firstName);
        await expect(newContactDialog.lastName).toHaveValue(lastName);
      });
      await test.step('3. Save Contact and verify creation', async () => {
        // Expected (APPROVED_REQUIREMENT; SF-219#AC2): Contact record is created and Contact detail page opens showing the entered Last Name
        await newContactDialog.saveButton.click();
        await waitForSpinners(page);
        await expectToast(page, lastName); // 1. the success toast names the record
        await expect(relatedListRecord(accountRecordPage.contactsRelatedList, lastName)).toBeVisible(); // 2. in the related list with that name
        await data.adopt('newContact', 'Contact', 'LastName', lastName); // code-owned cleanup: tagged by its run-unique name
        await relatedListRecord(accountRecordPage.contactsRelatedList, lastName).click(); // 3. opened from the related list
        await expectRecordTitle(page, lastName);
        {
          // 4. SOQL by the run tag: exactly this record, with the values entered
          const saved = await data.tagged('Contact', { LastName: lastName }, ['FirstName', 'LastName', 'Account.Name']);
          expect(saved).toHaveLength(1);
          expect(saved[0]).toMatchObject({
            FirstName: firstName,
            LastName: lastName,
            'Account.Name': data.value('Account', 'Name'),
          });
        }
        await expect.poll(() => soqlValue(sf, 'Contact', data.id('newContact'), 'LastName')).toBe(lastName);
      });
    },
  );
});
